struct iovec iov[1];
char data_buf[1024];
char control_buf[256];
ssize_t bytes_received;

iov[0].iov_base = data_buf;
iov[0].iov_len = sizeof(data_buf);

struct msghdr msg = {
    // Optional: msg_name/msg_namelen for address
    .msg_iov = iov,                 // Data buffers
    .msg_iovlen = 1,
    .msg_control = control_buf,     // Ancillary data buffer
    .msg_controllen = sizeof(control_buf)
    // .msg_flags (Output flags filled by kernel)
};

// Flags: e.g., MSG_PEEK, MSG_WAITALL, MSG_DONTWAIT
bytes_received = recvmsg(sockfd, &msg, MSG_WAITALL);

if (bytes_received > 0) {
    // Check msg.msg_flags for received status
    // Use CMSG_FIRSTHDR() to parse control data
}
